import { z } from 'zod';
import { positiveMoneySchema, uuidSchema } from '../common/schemas.js';

/** A percent with at most two decimals, 0.01–100. */
const percentSchema = z.number().positive().max(100).multipleOf(0.01);

const common = {
  /** Generated by the app, so an offline create can be retried */
  id: uuidSchema,
  goalId: uuidSchema,
  /** The account the money is taken from; amounts are in its currency */
  sourceAccountId: uuidSchema,
};

const scheduleFields = {
  frequency: z.enum(['daily', 'weekly', 'monthly']),
  /** Weekly: 1 = Monday … 7 = Sunday; today's when left out */
  weekday: z.number().int().min(1).max(7).nullable(),
  /** Monthly: 29–31 fall back to the last day of shorter months; today's when left out */
  dayOfMonth: z.number().int().min(1).max(31).nullable(),
};

/** A rule that moves money into a goal by itself (spec: «Автонакопления»). */
export const createAutoSaveSchema = z.discriminatedUnion('type', [
  z.object({
    ...common,
    type: z.literal('fixed_schedule'),
    amount: positiveMoneySchema,
    ...scheduleFields,
    weekday: scheduleFields.weekday.default(null),
    dayOfMonth: scheduleFields.dayOfMonth.default(null),
  }),
  z.object({
    ...common,
    type: z.literal('percent_of_income'),
    percent: percentSchema,
  }),
  z.object({
    ...common,
    type: z.literal('round_up'),
    /** 1 000 / 5 000 / 10 000 sums, or any step in the account's currency */
    roundTo: positiveMoneySchema,
  }),
]);
export type CreateAutoSaveInput = z.infer<typeof createAutoSaveSchema>;

/** Any field of the rule's own type; a paused rule does nothing until resumed. */
export const updateAutoSaveSchema = z
  .object({
    amount: positiveMoneySchema,
    percent: percentSchema,
    roundTo: positiveMoneySchema,
    ...scheduleFields,
    sourceAccountId: uuidSchema,
    isActive: z.boolean(),
  })
  .partial()
  .refine((patch) => Object.keys(patch).length > 0, 'Nothing to update');
export type UpdateAutoSaveInput = z.infer<typeof updateAutoSaveSchema>;

export const listAutoSaveQuerySchema = z.object({
  goalId: uuidSchema.optional(),
});
